export const n = 16;
export const num = "16";
export const title = "Clone، Fork و Upstream — ورود به کد دیگران";
export const label = "فصل ۱۶ · Clone و Fork";
export const part = 1;
export const html = "<p class=\"lead\">Clone = کپی مخزن روی رایانهٔ تو (با تاریخچه). Fork = کپی مخزن زیر حساب GitHub خودت. PR را باید از fork خودت به مخزن اصلی بفرستی؛ اگر فقط clone کرده باشی و حق push نداشته باشی، PR ساخته نمی‌شود.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>clone را با عمق و فیلتر درست انجام دهی</li>\n<li>fork را با <code>origin</code> و <code>upstream</code> بچینی</li>\n<li>شاخه را به‌روز نگه داری تا PR تمیز بماند</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">📥 clone</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">clone هوشمند</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>clone<span style=\"color: #F8F8F2\"> </span>git@github.com:rezaian-dev/javascript-persian-guide.git\ngit<span style=\"color: #F8F8F2\"> </span>clone<span style=\"color: #F8F8F2\"> </span>--depth<span style=\"color: #F8F8F2\"> </span><span style=\"color: #AE81FF\">1</span><span style=\"color: #F8F8F2\"> </span>&lt;url&gt;<span style=\"color: #F8F8F2\">              </span><span style=\"color: #959077\"># فقط نوک — سریع، تاریخچه ناقص</span>\ngit<span style=\"color: #F8F8F2\"> </span>clone<span style=\"color: #F8F8F2\"> </span>--filter<span style=\"color: #FF4689\">=</span>blob:none<span style=\"color: #F8F8F2\"> </span>&lt;url&gt;<span style=\"color: #F8F8F2\">     </span><span style=\"color: #959077\"># partial؛ blob تنبل</span>\ngh<span style=\"color: #F8F8F2\"> </span>repo<span style=\"color: #F8F8F2\"> </span>clone<span style=\"color: #F8F8F2\"> </span>rezaian-dev/javascript-persian-guide\n</pre></div>\n<div class=\"cols\">\n<div class=\"col\"><div class=\"col-title\">🖥️ VS Code + GitHub</div>\n<ol>\n<li>Palette: <code>Git: Clone</code> یا Welcome → <em>Clone Git Repository</em></li>\n<li>اگر افزونهٔ <strong>GitHub Pull Requests</strong> وصل است: <em>Clone from GitHub</em> و لیست ریپوهایت</li>\n<li>پوشه را انتخاب کن → <em>Open</em></li>\n<li>Fork از Command Palette: <code>GitHub Pull Requests: Fork</code></li>\n</ol>\n</div>\n<div class=\"col\"><div class=\"col-title\">⌨️ Terminal</div>\n<p><code>git clone git@github.com:org/repo.git</code>\n<code>gh repo clone org/repo</code>\n<code>gh repo fork org/repo --clone</code></p>\n</div>\n</div>\n<div class=\"callout callout-warn\"><div class=\"callout-title\">depth 1 و بعدش</div>\n<p>shallow clone برای CI عالی است. برای کار روزانه <code>bisect</code> و <code>blame</code> را ضعیف می‌کند. با <code>git fetch --unshallow</code> کاملش کن.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🍴 Fork — مدل مشارکت OSS</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">چیدمان استاندارد</span></div><pre>gh<span style=\"color: #F8F8F2\"> </span>repo<span style=\"color: #F8F8F2\"> </span>fork<span style=\"color: #F8F8F2\"> </span>rezaian-dev/javascript-persian-guide<span style=\"color: #F8F8F2\"> </span>--clone<span style=\"color: #FF4689\">=</span><span style=\"color: #F8F8F2\">true</span>\n<span style=\"color: #F8F8F2\">cd </span>javascript-persian-guide\ngit<span style=\"color: #F8F8F2\"> </span>remote<span style=\"color: #F8F8F2\"> </span>-v\n<span style=\"color: #959077\"># origin    تو (fork)</span>\n<span style=\"color: #959077\"># upstream  ریپوی اصلی</span>\n\ngit<span style=\"color: #F8F8F2\"> </span>fetch<span style=\"color: #F8F8F2\"> </span>upstream\ngit<span style=\"color: #F8F8F2\"> </span>switch<span style=\"color: #F8F8F2\"> </span>main\ngit<span style=\"color: #F8F8F2\"> </span>merge<span style=\"color: #F8F8F2\"> </span>--ff-only<span style=\"color: #F8F8F2\"> </span>upstream/main\ngit<span style=\"color: #F8F8F2\"> </span>push<span style=\"color: #F8F8F2\"> </span>origin<span style=\"color: #F8F8F2\"> </span>main\n</pre></div>\n<p class=\"keep-next\">قانون طلایی:</p>\n<ul>\n<li><strong>origin</strong> = ریپوی تو (حق push)</li>\n<li><strong>upstream</strong> = ریپوی صاحب پروژه (معمولاً read-only)</li>\n<li>PR از <code>origin/feat/x</code> به <code>upstream/main</code></li>\n</ul>\n<p>در GitHub دکمهٔ <em>Sync fork</em> همین merge را گرافیکی می‌کند. در VS Code افزونهٔ PR ریموت‌ها را می‌شناسد.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔁 مشارکت بدون fork — مدل تیمی</span></span></h2>\n<p class=\"keep-next\">در سازمان، معمولاً مستقیم روی ریپو دسترسی <code>write</code> داری:</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">شاخه روی origin</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>switch<span style=\"color: #F8F8F2\"> </span>-c<span style=\"color: #F8F8F2\"> </span>feat/docs<span style=\"color: #F8F8F2\"> </span>origin/main\ngit<span style=\"color: #F8F8F2\"> </span>push<span style=\"color: #F8F8F2\"> </span>-u<span style=\"color: #F8F8F2\"> </span>origin<span style=\"color: #F8F8F2\"> </span>HEAD\ngh<span style=\"color: #F8F8F2\"> </span>pr<span style=\"color: #F8F8F2\"> </span>create<span style=\"color: #F8F8F2\"> </span>--base<span style=\"color: #F8F8F2\"> </span>main\n</pre></div>\n<p>Fork برای OSS و پیمانکار خارجی است؛ برای همکار تمام‌وقت گام اضافه است.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — فرق clone و download ZIP؟</strong> ZIP بدون <code>.git</code> است؛ تاریخچه و شاخه ندارد.</p>\n<p><strong>Mid — چرا دو remote؟</strong> تا بتوانی از upstream بگیر و به origin هل بدهی بدون حق نوشتن روی اصلی.</p>\n<p><strong>Senior — fork network چیست؟</strong> گراف ریپوهای مشتق‌شده؛ GitHub objectها را تا حدی به اشتراک می‌گذارد. حذف fork تاریخچهٔ PR را پیچیده می‌کند.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>clone با SSH انجام داده‌ای</li>\n<li><code>origin</code>/<code>upstream</code> را درست نام‌گذاری می‌کنی</li>\n<li>Sync fork را قبل از PR تازه می‌زنی</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> Pull Request سطح Senior.</p></div>";
export default { n, num, title, label, part, html };
